namespace IAFahim.Geometry.Frame
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Mathematics;

    public static unsafe class ParallelTransport
    {
        private const float Zero = 0.0f;
        private const float One = 1.0f;
        private const float Two = 2.0f;
        private const float Threshold = 1e-6f;

        public static void Compute(float3* positions, int count, float3 initialNormal, float3* outRight, float3* outUp, float3* outForward)
        {
            if (count <= 0)
            {
                return;
            }

            if (count == 1)
            {
                float3 fwd = new float3(Zero, Zero, One);
                float3 up = math.normalize(initialNormal);
                if (math.abs(math.dot(fwd, up)) > One - Threshold)
                {
                    fwd = new float3(Zero, One, Zero);
                }
                float3 right = math.normalize(math.cross(up, fwd));
                fwd = math.normalize(math.cross(right, up));

                outForward[0] = fwd;
                outUp[0] = up;
                outRight[0] = right;
                return;
            }

            float3* tangents = stackalloc float3[count];
            for (int i = 0; i < count - 1; i++)
            {
                float3 diff = positions[i + 1] - positions[i];
                float len = math.length(diff);
                tangents[i] = len > Threshold ? diff / len : new float3(Zero, Zero, One);
            }
            tangents[count - 1] = tangents[count - 2];

            float3 t0 = tangents[0];
            float3 n0 = math.normalize(initialNormal);
            float dotT0N0 = math.dot(t0, n0);
            if (math.abs(dotT0N0) > One - Threshold)
            {
                float3 alt = new float3(Zero, One, Zero);
                if (math.abs(math.dot(t0, alt)) > One - Threshold)
                {
                    alt = new float3(Zero, Zero, One);
                }
                n0 = math.normalize(math.cross(t0, alt));
            }
            else
            {
                n0 = math.normalize(n0 - dotT0N0 * t0);
            }

            float3 b0 = math.normalize(math.cross(t0, n0));
            outForward[0] = t0;
            outUp[0] = n0;
            outRight[0] = b0;

            for (int i = 0; i < count - 1; i++)
            {
                float3 pI = positions[i];
                float3 pNext = positions[i + 1];
                float3 tI = tangents[i];
                float3 tNext = tangents[i + 1];
                float3 nI = outUp[i];

                float3 v1 = pNext - pI;
                float c1 = math.dot(v1, v1);

                float3 uI = nI;
                float3 tIL = tI;

                if (c1 > Threshold * Threshold)
                {
                    uI = nI - (Two / c1) * math.dot(v1, nI) * v1;
                    tIL = tI - (Two / c1) * math.dot(v1, tI) * v1;
                }

                float3 v2 = tNext - tIL;
                float c2 = math.dot(v2, v2);

                float3 nNext = uI;
                if (c2 > Threshold)
                {
                    nNext = uI - (Two / c2) * math.dot(v2, uI) * v2;
                }

                nNext = math.normalize(nNext);
                float3 bNext = math.normalize(math.cross(tNext, nNext));

                outForward[i + 1] = tNext;
                outUp[i + 1] = nNext;
                outRight[i + 1] = bNext;
            }
        }
    }
}

code.MaximumInscribedCircle.cs:
namespace IAFahim.Geometry.Hull
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MaximumInscribedCircle
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static double Cross(double x1, double y1, double x2, double y2, double x3, double y3)
        {
            return (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
        }

        private const double SearchHi = 2e9;
        private const int BisectionIterations = 60;
        private const int QueuePadding = 5;
        private const double HalfPlaneEpsilon = 1e-9;
        private const int MinFeasibleEdges = 3;
        private const double DeterminantEpsilon = 1e-12;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ComputeEdgeNormal(double* xs, double* ys, double* nx, double* ny, double* c, int i, int n)
        {
            int nxt = (i + 1) % n;
            double dx = xs[nxt] - xs[i];
            double dy = ys[nxt] - ys[i];
            double len = Math.Sqrt(dx * dx + dy * dy);
            nx[i] = -dy / len;
            ny[i] = dx / len;
            c[i] = xs[i] * nx[i] + ys[i] * ny[i];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool EdgeExcludesCorner(double* nx, double* ny, double* c, int prev, int curr, int test, double mid)
        {
            double px_curr, py_curr;
            Intersect(nx[prev], ny[prev], c[prev] + mid, nx[curr], ny[curr], c[curr] + mid, out px_curr, out py_curr);
            return nx[test] * px_curr + ny[test] * py_curr > c[test] + mid - HalfPlaneEpsilon;
        }

        public static double Run(double* xs, double* ys, int n)
        {
            if (n < MinFeasibleEdges) return 0;
            double lo = 0, hi = SearchHi;
            double* nx = stackalloc double[n];
            double* ny = stackalloc double[n];
            double* c = stackalloc double[n];

            for (int i = 0; i < n; i++)
            {
                ComputeEdgeNormal(xs, ys, nx, ny, c, i, n);
            }

            int* q = stackalloc int[n + QueuePadding];

            for (int iter = 0; iter < BisectionIterations; iter++)
            {
                double mid = (lo + hi) / 2;
                bool possible = true;

                int head = 0, tail = 0;

                q[tail++] = 0;
                q[tail++] = 1;

                for (int i = 2; i < n; i++)
                {
                    while (head + 1 < tail && EdgeExcludesCorner(nx, ny, c, q[tail - 2], q[tail - 1], i, mid)) tail--;
                    while (head + 1 < tail && EdgeExcludesCorner(nx, ny, c, q[head], q[head + 1], i, mid)) head++;
                    q[tail++] = i;
                }

                while (head + 1 < tail && EdgeExcludesCorner(nx, ny, c, q[tail - 2], q[tail - 1], q[head], mid)) tail--;

                if (tail - head < MinFeasibleEdges) possible = false;

                if (possible) lo = mid;
                else hi = mid;
            }
            return lo;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Intersect(double nx1, double ny1, double c1, double nx2, double ny2, double c2, out double x, out double y)
        {
            double det = nx1 * ny2 - ny1 * nx2;
            if (Math.Abs(det) < DeterminantEpsilon) { x = y = 0; return; }
            x = (c1 * ny2 - c2 * ny1) / det;
            y = (nx1 * c2 - nx2 * c1) / det;
        }
    }
}

code.MinkowskiSum.cs:
namespace IAFahim.Geometry.Hull
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MinkowskiSum
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Reorder(double* x, double* y, int n)
        {
            int minIdx = 0;
            for (int i = 1; i < n; i++)
            {
                if (y[i] < y[minIdx] || (y[i] == y[minIdx] && x[i] < x[minIdx]))
                    minIdx = i;
            }
            if (minIdx == 0) return;
            double* tx = stackalloc double[n];
            double* ty = stackalloc double[n];
            for (int i = 0; i < n; i++)
            {
                tx[i] = x[(minIdx + i) % n];
                ty[i] = y[(minIdx + i) % n];
            }
            for (int i = 0; i < n; i++)
            {
                x[i] = tx[i];
                y[i] = ty[i];
            }
        }

        public static int Convex(double* ax, double* ay, int an, double* bx, double* by, int bn, double* outX, double* outY)
        {
            if (an == 0 || bn == 0) return 0;
            Reorder(ax, ay, an);
            Reorder(bx, by, bn);

            int i = 0, j = 0, k = 0;
            outX[k] = ax[0] + bx[0];
            outY[k] = ay[0] + by[0];
            k++;

            int limit = an + bn;
            while (i < an || j < bn)
            {
                double dx1 = ax[(i + 1) % an] - ax[i % an];
                double dy1 = ay[(i + 1) % an] - ay[i % an];
                double dx2 = bx[(j + 1) % bn] - bx[j % bn];
                double dy2 = by[(j + 1) % bn] - by[j % bn];

                double cross = dx1 * dy2 - dy1 * dx2;

                double stepx, stepy;
                if (i < an && j < bn)
                {
                    if (cross >= 0) { stepx = dx1; stepy = dy1; i++; }
                    else { stepx = dx2; stepy = dy2; j++; }
                }
                else if (i < an) { stepx = dx1; stepy = dy1; i++; }
                else { stepx = dx2; stepy = dy2; j++; }

                // The closing edge reproduces the start vertex; do not write that
                // duplicate (it would overflow a buffer sized to the return value).
                if (k < limit)
                {
                    outX[k] = outX[k - 1] + stepx;
                    outY[k] = outY[k - 1] + stepy;
                    k++;
                }
            }
            return k;
        }

        public static int Difference(double* ax, double* ay, int an, double* bx, double* by, int bn, double* outX, double* outY)
        {
            double* nbx = stackalloc double[bn];
            double* nby = stackalloc double[bn];
            for (int i = 0; i < bn; i++)
            {
                nbx[i] = -bx[i];
                nby[i] = -by[i];
            }
            // Need to reverse the order so it remains counter-clockwise
            for (int i = 0; i < bn / 2; i++)
            {
                int opp = bn - 1 - i;
                double tx = nbx[i]; nbx[i] = nbx[opp]; nbx[opp] = tx;
                double ty = nby[i]; nby[i] = nby[opp]; nby[opp] = ty;
            }
            return Convex(ax, ay, an, nbx, nby, bn, outX, outY);
        }
    }
}

code.StraightSkeleton.cs:
namespace IAFahim.Geometry.Hull
{
    using System;
    using System.Runtime.CompilerServices;
    using System.Runtime.InteropServices;

    public static unsafe class StraightSkeleton
    {
        public struct Event { public double T; public int V1, V2; }

        public struct Node
        {
            public int Id;
            public double X, Y;
            public double Dx, Dy;
            public double Nx1, Ny1; // Normal of left edge
            public double Nx2, Ny2; // Normal of right edge
            public int Prev, Next;
            public bool Deleted;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static double IntersectTime(Node* nodes, int i, int j)
        {
            double xij = nodes[j].X - nodes[i].X;
            double yij = nodes[j].Y - nodes[i].Y;
            double dxij = nodes[j].Dx - nodes[i].Dx;
            double dyij = nodes[j].Dy - nodes[i].Dy;

            if (Math.Abs(dxij) < 1e-12 && Math.Abs(dyij) < 1e-12) return double.MaxValue;
            if (Math.Abs(dxij) < 1e-12)
            {
                if (Math.Abs(dyij) < 1e-12) return double.MaxValue;
                double t = -yij / dyij;
                if (Math.Abs(xij + dxij * t) > 1e-9) return double.MaxValue;
                return t > 1e-9 ? t : double.MaxValue;
            }
            double tX = -xij / dxij;
            if (Math.Abs(dyij) < 1e-12)
            {
                if (Math.Abs(yij + dyij * tX) > 1e-9) return double.MaxValue;
                return tX > 1e-9 ? tX : double.MaxValue;
            }
            double tY = -yij / dyij;
            if (Math.Abs(tX - tY) > 1e-9) return double.MaxValue;
            return tX > 1e-9 ? tX : double.MaxValue;
        }

        public static int Build(double* xs, double* ys, int n, double* outX, double* outY, Node* scratchNodes)
        {
            if (n < 3) return 0;
            Node* nodes = scratchNodes;
            int outCount = 0;

            for (int i = 0; i < n; i++)
            {
                int prev = (i - 1 + n) % n;
                int next = (i + 1) % n;

                double dx1 = xs[i] - xs[prev], dy1 = ys[i] - ys[prev];
                double len1 = Math.Sqrt(dx1 * dx1 + dy1 * dy1);
                dx1 /= len1; dy1 /= len1;

                double dx2 = xs[next] - xs[i], dy2 = ys[next] - ys[i];
                double len2 = Math.Sqrt(dx2 * dx2 + dy2 * dy2);
                dx2 /= len2; dy2 /= len2;

                double nx1 = -dy1, ny1 = dx1;
                double nx2 = -dy2, ny2 = dx2;

                double bx = nx1 + nx2, by = ny1 + ny2;
                double dot = bx * nx1 + by * ny1;

                nodes[i] = new Node 
                { 
                    Id = i, X = xs[i], Y = ys[i], 
                    Nx1 = nx1, Ny1 = ny1, Nx2 = nx2, Ny2 = ny2,
                    Prev = prev, Next = next, Deleted = false 
                };

                if (Math.Abs(dot) > 1e-12)
                {
                    double speed = 1.0 / dot;
                    nodes[i].Dx = bx * speed;
                    nodes[i].Dy = by * speed;
                }
            }

            int nextId = n;
            int activeCount = n;

            while (activeCount > 2)
            {
                double minT = double.MaxValue;
                int minI = -1, minJ = -1;

                for (int i = 0; i < nextId; i++)
                {
                    if (nodes[i].Deleted) continue;
                    int j = nodes[i].Next;
                    if (j == i) continue;
                    double t = IntersectTime(nodes, i, j);
                    if (t < minT)
                    {
                        minT = t;
                        minI = i;
                        minJ = j;
                    }
                }

                if (minI == -1) break;

                double meetX = nodes[minI].X + nodes[minI].Dx * minT;
                double meetY = nodes[minI].Y + nodes[minI].Dy * minT;

                outX[outCount] = nodes[minI].X; outY[outCount++] = nodes[minI].Y;
                outX[outCount] = meetX; outY[outCount++] = meetY;
                outX[outCount] = nodes[minJ].X; outY[outCount++] = nodes[minJ].Y;
                outX[outCount] = meetX; outY[outCount++] = meetY;

                int prevI = nodes[minI].Prev;
                int nextJ = nodes[minJ].Next;

                nodes[minI].Deleted = true;
                nodes[minJ].Deleted = true;
                activeCount -= 2;

                if (activeCount > 0)
                {
                    double nx1 = nodes[minI].Nx1, ny1 = nodes[minI].Ny1;
                    double nx2 = nodes[minJ].Nx2, ny2 = nodes[minJ].Ny2;

                    double bx = nx1 + nx2, by = ny1 + ny2;
                    double dot = bx * nx1 + by * ny1;

                    nodes[nextId] = new Node 
                    { 
                        Id = nextId, X = meetX, Y = meetY, 
                        Nx1 = nx1, Ny1 = ny1, Nx2 = nx2, Ny2 = ny2,
                        Prev = prevI, Next = nextJ, Deleted = false 
                    };

                    if (Math.Abs(dot) > 1e-12)
                    {
                        double speed = 1.0 / dot;
                        nodes[nextId].Dx = bx * speed;
                        nodes[nextId].Dy = by * speed;
                    }

                    nodes[prevI].Next = nextId;
                    nodes[nextJ].Prev = nextId;
                    nextId++;
                    activeCount++;
                }
            }

            return outCount / 2; // Returns number of segments
        }
    }
}

