namespace IAFahim.Geometry.Intersect
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Polyhedron
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Volume(double* xs, double* ys, double* zs, int* faces, int faceCount)
        {
            double vol = 0.0;
            for (int i = 0; i < faceCount; i++)
            {
                int a = faces[i * 3];
                int b = faces[i * 3 + 1];
                int c = faces[i * 3 + 2];

                double v1x = xs[b] - xs[a];
                double v1y = ys[b] - ys[a];
                double v1z = zs[b] - zs[a];

                double v2x = xs[c] - xs[a];
                double v2y = ys[c] - ys[a];
                double v2z = zs[c] - zs[a];

                double cx = v1y * v2z - v1z * v2y;
                double cy = v1z * v2x - v1x * v2z;
                double cz = v1x * v2y - v1y * v2x;

                vol += xs[a] * cx + ys[a] * cy + zs[a] * cz;
            }
            return Math.Abs(vol) / 6.0;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Faces(int vertexCount, int edgeCount)
        {
            return 2 - vertexCount + edgeCount;
        }
    }
}

code.Sphere.cs:
namespace IAFahim.Geometry.Intersect
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Sphere
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int LineIntersection(
            double cx, double cy, double cz, double r, 
            double lx, double ly, double lz, 
            double ldx, double ldy, double ldz, 
            double* t1, double* t2)
        {
            double fx = lx - cx;
            double fy = ly - cy;
            double fz = lz - cz;

            double a = ldx * ldx + ldy * ldy + ldz * ldz;
            if (a < 1e-24) return 0;

            double b = 2.0 * (fx * ldx + fy * ldy + fz * ldz);
            double c = fx * fx + fy * fy + fz * fz - r * r;

            double disc = b * b - 4.0 * a * c;
            if (disc < -1e-12) return 0;

            if (disc < 1e-12)
            {
                *t1 = -b / (2.0 * a);
                *t2 = *t1;
                return 1;
            }

            double sq = Math.Sqrt(disc);
            double q = (b > 0) ? -0.5 * (b + sq) : -0.5 * (b - sq);

            double r1 = q / a;
            double r2 = c / q;

            if (r1 > r2)
            {
                *t1 = r2;
                *t2 = r1;
            }
            else
            {
                *t1 = r1;
                *t2 = r2;
            }

            return 2;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool SphereIntersection(
            double x1, double y1, double z1, double r1, 
            double x2, double y2, double z2, double r2, 
            double* cx, double* cy, double* cz,
            double* circleRadius,
            double* nx, double* ny, double* nz)
        {
            double dx = x2 - x1;
            double dy = y2 - y1;
            double dz = z2 - z1;
            double dSq = dx * dx + dy * dy + dz * dz;
            double d = Math.Sqrt(dSq);

            if (d > r1 + r2 + 1e-12) return false;
            if (d < Math.Abs(r1 - r2) - 1e-12) return false;
            if (d < 1e-12) return false;

            double a = (r1 * r1 - r2 * r2 + dSq) / (2.0 * d);
            double hSq = r1 * r1 - a * a;
            double h = hSq > 0 ? Math.Sqrt(hSq) : 0.0;

            *cx = x1 + a * (dx / d);
            *cy = y1 + a * (dy / d);
            *cz = z1 + a * (dz / d);

            *circleRadius = h;

            *nx = dx / d;
            *ny = dy / d;
            *nz = dz / d;

            return true;
        }
    }
}

code.Plane.cs:
namespace IAFahim.Geometry.Intersect
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Plane
    {
        // Signed distance for a possibly non-unit normal (n is not assumed normalized).
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double PointPlaneDistance(double px, double py, double pz, double nx, double ny, double nz, double d)
        {
            return (px * nx + py * ny + pz * nz + d) / Math.Sqrt(nx * nx + ny * ny + nz * nz);
        }

        // Signed distance when the caller guarantees (nx,ny,nz) is unit length; skips the sqrt.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double PointPlaneDistanceNormalized(double px, double py, double pz, double nx, double ny, double nz, double d)
        {
            return px * nx + py * ny + pz * nz + d;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool LinePlaneIntersection(double lx, double ly, double lz, double ldx, double ldy, double ldz, double nx, double ny, double nz, double d, double* t)
        {
            double denom = nx * ldx + ny * ldy + nz * ldz;
            if (Math.Abs(denom) < 1e-12) return false;
            *t = -(nx * lx + ny * ly + nz * lz + d) / denom;
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool SegmentPlaneIntersection(double x1, double y1, double z1, double x2, double y2, double z2, double nx, double ny, double nz, double d, double* t)
        {
            double dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
            double denom = nx * dx + ny * dy + nz * dz;
            if (Math.Abs(denom) < 1e-12) return false;
            double param = -(nx * x1 + ny * y1 + nz * z1 + d) / denom;
            if (param < 0.0 || param > 1.0) return false;
            *t = param; return true;
        }

        public static bool PlaneIntersection(double n1x, double n1y, double n1z, double d1, double n2x, double n2y, double n2z, double d2,
                                             double* lpx, double* lpy, double* lpz, double* ldx, double* ldy, double* ldz)
        {
            double dx = n1y * n2z - n1z * n2y;
            double dy = n1z * n2x - n1x * n2z;
            double dz = n1x * n2y - n1y * n2x;
            *ldx = dx; *ldy = dy; *ldz = dz;
            double dirSq = dx * dx + dy * dy + dz * dz;
            if (dirSq < 1e-24) return false;
            double ax = Math.Abs(dx);
            double ay = Math.Abs(dy);
            double az = Math.Abs(dz);
            if (ax >= ay && ax >= az) SolvePoint(lpx, lpy, lpz, n1y, n1z, d1, n2y, n2z, d2, dx);
            else if (ay >= ax && ay >= az) SolvePoint(lpy, lpz, lpx, n1z, n1x, d1, n2z, n2x, d2, dy);
            else SolvePoint(lpz, lpx, lpy, n1x, n1y, d1, n2x, n2y, d2, dz);
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void SolvePoint(double* pFixed, double* p1, double* p2, double a1, double b1, double d1, double a2, double b2, double d2, double det)
        {
            *pFixed = 0.0;
            *p1 = (-d1 * b2 + d2 * b1) / det;
            *p2 = (-a1 * d2 + a2 * d1) / det;
        }
    }
}

code.MeshProjection.cs:
namespace IAFahim.Geometry.Mesh
{
    using System;
    using System.Runtime.CompilerServices;
    using Unity.Mathematics;

    public static unsafe class MeshProjection
    {
        private const float Zero = 0.0f;
        private const float One = 1.0f;
        private const float Epsilon = 1e-6f;

        public static void DeformVertices(
            float3* inVertices, 
            float3* inNormals, 
            int vertexCount, 
            float3* pathPositions, 
            float3* pathRights, 
            float3* pathUps, 
            float3* pathForwards, 
            int pathCount,
            float* vertexU, // normalized parameter [0, 1] along the path for each vertex
            float3 scale, 
            float3* outVertices, 
            float3* outNormals)
        {
            if (pathCount <= 0 || vertexCount <= 0)
            {
                return;
            }

            for (int i = 0; i < vertexCount; i++)
            {
                float val = vertexU[i];
                float u = math.isnan(val) ? Zero : math.clamp(val, Zero, One);
                float floatIdx = u * (float)(pathCount - 1);
                int idx0 = (int)math.floor(floatIdx);
                int idx1 = math.min(idx0 + 1, pathCount - 1);
                float t = floatIdx - (float)idx0;

                float3 p0 = pathPositions[idx0];
                float3 p1 = pathPositions[idx1];
                float3 r0 = pathRights[idx0];
                float3 r1 = pathRights[idx1];
                float3 u0 = pathUps[idx0];
                float3 u1 = pathUps[idx1];
                float3 f0 = pathForwards[idx0];
                float3 f1 = pathForwards[idx1];

                float3 p = math.lerp(p0, p1, t);
                float3 r = SafeNormalize(math.lerp(r0, r1, t), new float3(One, Zero, Zero));
                float3 upVec = SafeNormalize(math.lerp(u0, u1, t), new float3(Zero, One, Zero));
                float3 f = SafeNormalize(math.lerp(f0, f1, t), new float3(Zero, Zero, One));

                float3 vLocal = inVertices[i];
                float3 vDeformed = p + vLocal.x * r * scale.x + vLocal.y * upVec * scale.y;
                outVertices[i] = vDeformed;

                if (inNormals != null && outNormals != null)
                {
                    float3 nLocal = inNormals[i];
                    float3 nDeformed = nLocal.x * r + nLocal.y * upVec + nLocal.z * f;
                    float len = math.length(nDeformed);
                    outNormals[i] = len > Epsilon ? nDeformed / len : upVec;
                }
            }
        }

        public static void RecalculateNormals(
            float3* vertices, 
            int vertexCount, 
            int* indices, 
            int indexCount, 
            float3* outNormals)
        {
            if (vertexCount <= 0)
            {
                return;
            }

            for (int i = 0; i < vertexCount; i++)
            {
                outNormals[i] = new float3(Zero, Zero, Zero);
            }

            int triangleCount = indexCount / 3;
            for (int i = 0; i < triangleCount; i++)
            {
                int idx0 = indices[i * 3];
                int idx1 = indices[i * 3 + 1];
                int idx2 = indices[i * 3 + 2];

                float3 v0 = vertices[idx0];
                float3 v1 = vertices[idx1];
                float3 v2 = vertices[idx2];

                float3 edge1 = v1 - v0;
                float3 edge2 = v2 - v0;
                float3 faceNormal = math.cross(edge1, edge2);

                outNormals[idx0] += faceNormal;
                outNormals[idx1] += faceNormal;
                outNormals[idx2] += faceNormal;
            }

            for (int i = 0; i < vertexCount; i++)
            {
                float len = math.length(outNormals[i]);
                outNormals[i] = len > Epsilon ? outNormals[i] / len : new float3(Zero, One, Zero);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static float3 SafeNormalize(float3 v, float3 fallback)
        {
            float len = math.length(v);
            return len > Epsilon ? v / len : fallback;
        }
    }
}

