namespace IAFahim.Geometry.Spatial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class CoverTree
    {
        public struct Node { public double X, Y; public int Level; public int Next; }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build(double* xs, double* ys, int n, Node* nodes)
        {
            for (int i = 0; i < n; i++) { nodes[i].X = xs[i]; nodes[i].Y = ys[i]; nodes[i].Level = 0; nodes[i].Next = -1; }
            return n;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Nearest(Node* nodes, int n, double qx, double qy)
        {
            if (n <= 0) return -1;
            int best = -1;
            double bd = double.MaxValue;
            for (int i = 0; i < n; i++)
            {
                double dx = nodes[i].X - qx, dy = nodes[i].Y - qy;
                double d = dx * dx + dy * dy;
                if (d < bd) { bd = d; best = i; }
            }
            return best;
        }
    }
}

code.KdTree.cs:
namespace IAFahim.Geometry.Spatial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class KdTree
    {
        public struct Node
        {
            public double X, Y;
            public int PointIndex;
            public int Left, Right;
            public int Axis;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build(double* xs, double* ys, int n, Node* nodes)
        {
            if (n == 0) return 0;

            int* indices = stackalloc int[n];
            for (int i = 0; i < n; i++) indices[i] = i;

            int nodeCount = 0;
            BuildRecursive(xs, ys, nodes, indices, n, 0, ref nodeCount);
            return nodeCount;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int BuildRecursive(double* xs, double* ys, Node* nodes, int* indices, int count, int depth, ref int nodeCount)
        {
            if (count == 0) return -1;

            int axis = depth % 2;

            // Sort indices based on axis (heapsort, O(n log n))
            SortIndicesByAxis(xs, ys, indices, count, axis);

            int mid = count / 2;
            int u = nodeCount++;

            nodes[u].PointIndex = indices[mid];
            nodes[u].X = xs[indices[mid]];
            nodes[u].Y = ys[indices[mid]];
            nodes[u].Axis = axis;

            nodes[u].Left = BuildRecursive(xs, ys, nodes, indices, mid, depth + 1, ref nodeCount);

            int rightCount = count - mid - 1;
            nodes[u].Right = BuildRecursive(xs, ys, nodes, indices + mid + 1, rightCount, depth + 1, ref nodeCount);

            return u;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static double AxisKey(double* xs, double* ys, int idx, int axis) => axis == 0 ? xs[idx] : ys[idx];

        private static void SortIndicesByAxis(double* xs, double* ys, int* indices, int count, int axis)
        {
            for (int i = (count >> 1) - 1; i >= 0; i--) SiftDown(xs, ys, indices, i, count, axis);
            for (int end = count - 1; end > 0; end--)
            {
                int t = indices[0]; indices[0] = indices[end]; indices[end] = t;
                SiftDown(xs, ys, indices, 0, end, axis);
            }
        }

        private static void SiftDown(double* xs, double* ys, int* a, int i, int n, int axis)
        {
            while (true)
            {
                int l = 2 * i + 1, r = 2 * i + 2, m = i;
                if (l < n && AxisKey(xs, ys, a[l], axis) > AxisKey(xs, ys, a[m], axis)) m = l;
                if (r < n && AxisKey(xs, ys, a[r], axis) > AxisKey(xs, ys, a[m], axis)) m = r;
                if (m == i) break;
                int t = a[i]; a[i] = a[m]; a[m] = t;
                i = m;
            }
        }
    }
}

code.Quadtree.cs:
namespace IAFahim.Geometry.Spatial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Quadtree
    {
        private const int QuadrantCount = 4;

        private const int QuadrantLowerLeft = 0;

        private const int QuadrantLowerRight = 1;

        private const int QuadrantUpperLeft = 2;

        private const int QuadrantUpperRight = 3;

        private const double MidpointWeight = 0.5;

        private const int NoChild = -1;

        private const int NoPoint = -1;

        public struct Node
        {
            public double MinX, MinY, MaxX, MaxY;
            public int FirstChild;
            public int PointIndex;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ComputeBoundingBox(double* xs, double* ys, int n, out double minX, out double minY, out double maxX, out double maxY)
        {
            minX = xs[0]; minY = ys[0]; maxX = xs[0]; maxY = ys[0];
            for (int i = 1; i < n; i++)
            {
                if (xs[i] < minX) minX = xs[i];
                if (xs[i] > maxX) maxX = xs[i];
                if (ys[i] < minY) minY = ys[i];
                if (ys[i] > maxY) maxY = ys[i];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsInQuadrant(double px, double py, double midX, double midY, int quadrant)
        {
            bool lowerY = py <= midY;
            bool leftX = px <= midX;
            switch (quadrant)
            {
                case QuadrantLowerLeft: return leftX && lowerY;
                case QuadrantLowerRight: return !leftX && lowerY;
                case QuadrantUpperLeft: return leftX && !lowerY;
                default: return !leftX && !lowerY;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int PartitionQuadrant(double* xs, double* ys, int* indices, int lo, int count, double midX, double midY, int quadrant)
        {
            int matched = 0;
            for (int i = lo; i < count; i++)
            {
                int p = indices[i];
                if (IsInQuadrant(xs[p], ys[p], midX, midY, quadrant))
                {
                    int t = indices[lo + matched];
                    indices[lo + matched] = indices[i];
                    indices[i] = t;
                    matched++;
                }
            }
            return matched;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ConfigureQuadrantBounds(Node* nodes, int first, int u, double midX, double midY, int quadrant)
        {
            Node* child = &nodes[first + quadrant];
            switch (quadrant)
            {
                case QuadrantLowerLeft:
                    child->MinX = nodes[u].MinX; child->MaxX = midX;
                    child->MinY = nodes[u].MinY; child->MaxY = midY;
                    break;
                case QuadrantLowerRight:
                    child->MinX = midX; child->MaxX = nodes[u].MaxX;
                    child->MinY = nodes[u].MinY; child->MaxY = midY;
                    break;
                case QuadrantUpperLeft:
                    child->MinX = nodes[u].MinX; child->MaxX = midX;
                    child->MinY = midY; child->MaxY = nodes[u].MaxY;
                    break;
                default:
                    child->MinX = midX; child->MaxX = nodes[u].MaxX;
                    child->MinY = midY; child->MaxY = nodes[u].MaxY;
                    break;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build(double* xs, double* ys, int n, Node* nodes, int maxNodes)
        {
            if (n == 0 || maxNodes < 1) return 0;
            ComputeBoundingBox(xs, ys, n, out double minX, out double minY, out double maxX, out double maxY);
            int nodeCount = 1;
            nodes[0].MinX = minX; nodes[0].MinY = minY;
            nodes[0].MaxX = maxX; nodes[0].MaxY = maxY;
            nodes[0].FirstChild = NoChild;
            nodes[0].PointIndex = NoPoint;
            int* indices = stackalloc int[n];
            for (int i = 0; i < n; i++) indices[i] = i;
            BuildRecursive(xs, ys, nodes, 0, indices, n, ref nodeCount, maxNodes);
            return nodeCount;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void BuildRecursive(double* xs, double* ys, Node* nodes, int u, int* indices, int count, ref int nodeCount, int maxNodes)
        {
            if (count == 0) return;
            if (count == 1)
            {
                nodes[u].PointIndex = indices[0];
                return;
            }
            if (nodeCount + QuadrantCount > maxNodes)
            {
                nodes[u].PointIndex = indices[0];
                return;
            }

            double midX = (nodes[u].MinX + nodes[u].MaxX) * MidpointWeight;
            double midY = (nodes[u].MinY + nodes[u].MaxY) * MidpointWeight;

            int first = nodeCount;
            nodes[u].FirstChild = first;
            nodeCount += QuadrantCount;

            for (int i = 0; i < QuadrantCount; i++)
            {
                nodes[first + i].FirstChild = NoChild;
                nodes[first + i].PointIndex = NoPoint;
                ConfigureQuadrantBounds(nodes, first, u, midX, midY, i);
            }

            int n0 = PartitionQuadrant(xs, ys, indices, 0, count, midX, midY, QuadrantLowerLeft);
            int n1 = PartitionQuadrant(xs, ys, indices, n0, count, midX, midY, QuadrantLowerRight);
            int n2 = PartitionQuadrant(xs, ys, indices, n0 + n1, count, midX, midY, QuadrantUpperLeft);
            int n3 = count - n0 - n1 - n2;

            int* c0Start = indices;
            int* c1Start = indices + n0;
            int* c2Start = c1Start + n1;
            int* c3Start = c2Start + n2;

            BuildRecursive(xs, ys, nodes, first, c0Start, n0, ref nodeCount, maxNodes);
            BuildRecursive(xs, ys, nodes, first + 1, c1Start, n1, ref nodeCount, maxNodes);
            BuildRecursive(xs, ys, nodes, first + 2, c2Start, n2, ref nodeCount, maxNodes);
            BuildRecursive(xs, ys, nodes, first + 3, c3Start, n3, ref nodeCount, maxNodes);
        }
    }
}

code.RangeTree.cs:
namespace IAFahim.Geometry.Spatial
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class RangeTree
    {
        private const int AxisX = 0;

        private const int AxisY = 1;

        private const int AxisZ = 2;

        private const int AxisCount2D = 2;

        private const int AxisCount3D = 3;

        public struct Node
        {
            public double X, Y, Z;
            public int Left, Right;
            public int OriginalIndex;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static double CoordOnAxis(int axis, double* xs, double* ys, double* zs, int* idx, int i)
        {
            return axis == AxisX ? xs[idx[i]] : (axis == AxisY ? ys[idx[i]] : zs[idx[i]]);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PartitionAround(int axis, double* xs, double* ys, double* zs, int* idx, int start, int end, int k)
        {
            int l = start, r = end;
            while (l < r)
            {
                double pivot = CoordOnAxis(axis, xs, ys, zs, idx, k);
                int i = l, j = r;
                while (i <= j)
                {
                    while (CoordOnAxis(axis, xs, ys, zs, idx, i) < pivot) i++;
                    while (CoordOnAxis(axis, xs, ys, zs, idx, j) > pivot) j--;
                    if (i <= j)
                    {
                        int t = idx[i]; idx[i] = idx[j]; idx[j] = t;
                        i++; j--;
                    }
                }
                if (j < k) l = i;
                if (k < i) r = j;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int AllocNode(Node* nodes, ref int nextFree, double* xs, double* ys, double* zs, int* idx, int mid, bool is3D)
        {
            int rootIdx = nextFree++;
            int originalId = idx[mid];
            nodes[rootIdx].X = xs[originalId];
            nodes[rootIdx].Y = ys[originalId];
            if (is3D) nodes[rootIdx].Z = zs[originalId];
            nodes[rootIdx].OriginalIndex = originalId;
            return rootIdx;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build2D(double* xs, double* ys, int n, Node* nodes)
        {
            if (n <= 0) return -1;
            int* idx = stackalloc int[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            int nextFree = 0;
            return BuildRec(xs, ys, null, idx, 0, n - 1, nodes, ref nextFree, 0, false);
        }

        private static int BuildRec(double* xs, double* ys, double* zs, int* idx, int start, int end, Node* nodes, ref int nextFree, int depth, bool is3D)
        {
            if (start > end) return -1;
            int mid = start + (end - start) / 2;
            int axis = is3D ? (depth % AxisCount3D) : (depth % AxisCount2D);
            PartitionAround(axis, xs, ys, zs, idx, start, end, mid);
            int rootIdx = AllocNode(nodes, ref nextFree, xs, ys, zs, idx, mid, is3D);
            nodes[rootIdx].Left = BuildRec(xs, ys, zs, idx, start, mid - 1, nodes, ref nextFree, depth + 1, is3D);
            nodes[rootIdx].Right = BuildRec(xs, ys, zs, idx, mid + 1, end, nodes, ref nextFree, depth + 1, is3D);
            return rootIdx;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Query2D(Node* nodes, int root, double x1, double y1, double x2, double y2, int* outIdx)
        {
            int count = 0;
            QueryRec(nodes, root, x1, y1, x2, y2, outIdx, ref count, 0);
            return count;
        }

        private static void QueryRec(Node* nodes, int node, double x1, double y1, double x2, double y2, int* outIdx, ref int count, int depth)
        {
            if (node < 0) return;
            Node* n = &nodes[node];

            bool inRange = n->X >= x1 && n->X <= x2 && n->Y >= y1 && n->Y <= y2;
            if (inRange) outIdx[count++] = n->OriginalIndex;

            int axis = depth % AxisCount2D;
            double val = axis == 0 ? n->X : n->Y;
            double minV = axis == 0 ? x1 : y1;
            double maxV = axis == 0 ? x2 : y2;

            if (minV <= val) QueryRec(nodes, n->Left, x1, y1, x2, y2, outIdx, ref count, depth + 1);
            if (maxV >= val) QueryRec(nodes, n->Right, x1, y1, x2, y2, outIdx, ref count, depth + 1);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Build3D(double* xs, double* ys, double* zs, int n, Node* nodes)
        {
            if (n <= 0) return -1;
            int* idx = stackalloc int[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            int nextFree = 0;
            return BuildRec(xs, ys, zs, idx, 0, n - 1, nodes, ref nextFree, 0, true);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Query3D(Node* nodes, int root, double x1, double y1, double z1, double x2, double y2, double z2, int* outIdx)
        {
            int count = 0;
            QueryRec3D(nodes, root, x1, y1, z1, x2, y2, z2, outIdx, ref count, 0);
            return count;
        }

        private static void QueryRec3D(Node* nodes, int node, double x1, double y1, double z1, double x2, double y2, double z2, int* outIdx, ref int count, int depth)
        {
            if (node < 0) return;
            Node* n = &nodes[node];

            bool inRange = n->X >= x1 && n->X <= x2 && n->Y >= y1 && n->Y <= y2 && n->Z >= z1 && n->Z <= z2;
            if (inRange) outIdx[count++] = n->OriginalIndex;

            int axis = depth % AxisCount3D;
            double val = axis == 0 ? n->X : (axis == 1 ? n->Y : n->Z);
            double minV = axis == 0 ? x1 : (axis == 1 ? y1 : z1);
            double maxV = axis == 0 ? x2 : (axis == 1 ? y2 : z2);

            if (minV <= val) QueryRec3D(nodes, n->Left, x1, y1, z1, x2, y2, z2, outIdx, ref count, depth + 1);
            if (maxV >= val) QueryRec3D(nodes, n->Right, x1, y1, z1, x2, y2, z2, outIdx, ref count, depth + 1);
        }
    }
}

