        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ProcessAugmentingPath(int v, int u, int* match, int* parent)
        {
            parent[v] = u;
            int cur = v;
            while (cur != -1)
            {
                int pNode = parent[cur];
                int nextMatched = match[pNode];
                match[cur] = pNode;
                match[pNode] = cur;
                cur = nextMatched;
            }
            return true;
