    public static unsafe class MstVariants
    {
        public static long MinimumArborescenceDirected(int n, int root, int* u, int* v, long* w, int m, long* result)
        {
            return ChuLiuEdmonds.Run(n, root, u, v, w, m, result);
        }

        public static long MaximumBranching(int n, int* u, int* v, long* w, int m, int* resultEdges, int* resultCount)
        {
            int dummyRoot = n;
            int newN = n + 1;
            int newM = m + n;

            int* newU = stackalloc int[newM];
            int* newV = stackalloc int[newM];
            long* newW = stackalloc long[newM];

            long maxW = 0;
            for (int i = 0; i < m; i++)
            {
                if (w[i] > maxW)
                {
                    maxW = w[i];
                }
            }

            for (int i = 0; i < m; i++)
            {
                newU[i] = u[i];
                newV[i] = v[i];
                newW[i] = maxW - w[i];
            }

            for (int i = 0; i < n; i++)
            {
                newU[m + i] = dummyRoot;
                newV[m + i] = i;
                newW[m + i] = maxW;
            }

            long* result = stackalloc long[newN];
            for (int i = 0; i < newN; i++)
            {
                result[i] = -1;
            }

            long minArbWeight = ChuLiuEdmonds.Run(newN, dummyRoot, newU, newV, newW, newM, result);
            if (minArbWeight == -1)
            {
                return -1;
            }

            *resultCount = 0;
            long totalWeight = 0;
            for (int i = 0; i < newN; i++)
            {
                if (i != dummyRoot && result[i] != -1)
                {
                    int parent = (int)result[i];
                    if (parent != dummyRoot)
                    {
                        AppendBranchingEdge(parent, i, u, v, w, m, resultEdges, resultCount, ref totalWeight);
                    }
                }
            }

            return totalWeight;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void AppendBranchingEdge(int parent, int target, int* u, int* v, long* w, int m, int* resultEdges, int* resultCount, ref long totalWeight)
        {
            for (int e = 0; e < m; e++)
            {
                if (u[e] == parent && v[e] == target)
                {
                    resultEdges[(*resultCount)++] = e;
                    totalWeight += w[e];
                    return;
                }
            }
        }

        public static long BranchingMatroidIntersection(int n, int* u, int* v, long* w, int m, int* resultEdges, int* resultCount)
        {
            return MaximumBranching(n, u, v, w, m, resultEdges, resultCount);
        }

        public static long ArborescenceCount(int n, int root, int* u, int* v, int m)
        {
            const long Mod = 1000000007;
            long* laplacian = stackalloc long[(n - 1) * (n - 1)];
            for (int i = 0; i < (n - 1) * (n - 1); i++)
            {
                laplacian[i] = 0;
            }

            int* map = stackalloc int[n];
            int idx = 0;
            for (int i = 0; i < n; i++)
            {
                if (i == root)
                {
                    map[i] = -1;
                }
                else
                {
                    map[i] = idx++;
                }
            }

            for (int i = 0; i < m; i++)
            {
                int fromNode = u[i];
                int toNode = v[i];
                if (toNode == root)
                {
                    continue;
                }
                int mappedTo = map[toNode];
                laplacian[mappedTo * (n - 1) + mappedTo]++;

                if (fromNode != root)
                {
                    int mappedFrom = map[fromNode];
                    laplacian[mappedTo * (n - 1) + mappedFrom] = (laplacian[mappedTo * (n - 1) + mappedFrom] - 1 + Mod) % Mod;
                }
            }

            long det = 1;
            int dim = n - 1;
            for (int i = 0; i < dim; i++)
            {
                int pivot = SelectPivotRow(laplacian, dim, i);
                if (laplacian[pivot * dim + i] == 0)
                {
                    return 0;
                }
                if (pivot != i)
                {
                    SwapRows(laplacian, dim, i, pivot);
                    det = (Mod - det) % Mod;
                }
                det = (det * laplacian[i * dim + i]) % Mod;
                long inv = Power(laplacian[i * dim + i], Mod - 2, Mod);
                EliminateBelow(laplacian, dim, i, inv, Mod);
            }
            return det;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int SelectPivotRow(long* laplacian, int dim, int i)
        {
            int pivot = i;
            for (int j = i + 1; j < dim; j++)
            {
                if (Math.Abs(laplacian[j * dim + i]) > Math.Abs(laplacian[pivot * dim + i]))
                {
                    pivot = j;
                }
            }
            return pivot;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void SwapRows(long* laplacian, int dim, int i, int pivot)
        {
            for (int k = 0; k < dim; k++)
            {
                long tmp = laplacian[i * dim + k];
                laplacian[i * dim + k] = laplacian[pivot * dim + k];
                laplacian[pivot * dim + k] = tmp;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void EliminateBelow(long* laplacian, int dim, int i, long inv, long mod)
        {
            for (int j = i + 1; j < dim; j++)
            {
                long factor = (laplacian[j * dim + i] * inv) % mod;
                for (int k = i; k < dim; k++)
                {
                    laplacian[j * dim + k] = (laplacian[j * dim + k] - factor * laplacian[i * dim + k] % mod + mod) % mod;
                }
            }
        }

        private static long Power(long baseVal, long exp, long mod)
        {
            long res = 1;
            baseVal %= mod;
            while (exp > 0)
            {
                if (exp % 2 == 1)
                {
                    res = (res * baseVal) % mod;
                }
                baseVal = (baseVal * baseVal) % mod;
                exp /= 2;
            }
            return res;
        }

        public static bool DegreeConstrainedMst(int n, int m, int* u, int* v, long* w, int r, int k, int* resultEdges, int* resultCount)
        {
            int* parent = stackalloc int[n];
            int* rank = stackalloc int[n];
            int* edgeIndices = stackalloc int[m];
            for (int i = 0; i < m; i++)
            {
                edgeIndices[i] = i;
            }

            for (int i = 0; i < m; i++)
            {
                for (int j = i + 1; j < m; j++)
                {
                    if (w[edgeIndices[i]] > w[edgeIndices[j]])
                    {
                        int tmp = edgeIndices[i];
                        edgeIndices[i] = edgeIndices[j];
                        edgeIndices[j] = tmp;
                    }
                }
            }

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                rank[i] = 0;
            }

            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            bool Union(int x, int y)
            {
                int rx = Find(x);
                int ry = Find(y);
                if (rx == ry)
                {
                    return false;
                }
                if (rank[rx] < rank[ry])
                {
                    parent[rx] = ry;
                }
                else if (rank[rx] > rank[ry])
                {
                    parent[ry] = rx;
                }
                else
                {
                    parent[ry] = rx;
                    rank[rx]++;
                }
                return true;
            }

            byte* inTree = stackalloc byte[m];
            for (int i = 0; i < m; i++)
            {
                inTree[i] = 0;
            }

            int components = n - 1;
            for (int i = 0; i < m; i++)
            {
                int e = edgeIndices[i];
                if (u[e] == r || v[e] == r)
                {
                    continue;
                }
                if (Union(u[e], v[e]))
                {
                    inTree[e] = 1;
                    components--;
                }
            }

            int* minEdgeToR = stackalloc int[n];
            for (int i = 0; i < n; i++)
            {
                minEdgeToR[i] = -1;
            }

            for (int i = 0; i < m; i++)
            {
                int e = edgeIndices[i];
                if (u[e] == r || v[e] == r)
                {
                    int other = (u[e] == r) ? v[e] : u[e];
                    int rootComp = Find(other);
                    if (minEdgeToR[rootComp] == -1 || w[e] < w[minEdgeToR[rootComp]])
                    {
                        minEdgeToR[rootComp] = e;
                    }
                }
            }

            int deg = 0;
            for (int i = 0; i < n; i++)
            {
                if (i != r && Find(i) == i)
                {
                    int e = minEdgeToR[i];
                    if (e == -1)
                    {
                        return false;
                    }
                    inTree[e] = 1;
                    deg++;
                }
            }

            if (deg > k)
            {
                return false;
            }

            while (deg < k)
            {
                int bestEdgeToAdd = -1;
                int bestEdgeToRemove = -1;
                long maxReduction = 0;

                for (int eAdd = 0; eAdd < m; eAdd++)
                {
                    if (inTree[eAdd] == 1)
                    {
                        continue;
                    }
                    if (u[eAdd] != r && v[eAdd] != r)
                    {
                        continue;
                    }

                    int other = (u[eAdd] == r) ? v[eAdd] : u[eAdd];

                    int* head = stackalloc int[n];
                    int* next = stackalloc int[n * 2];
                    int* to = stackalloc int[n * 2];
                    int* edgeId = stackalloc int[n * 2];
                    for (int i = 0; i < n; i++)
                    {
                        head[i] = -1;
                    }

                    int edgeIdx = 0;
                    for (int e = 0; e < m; e++)
                    {
                        if (inTree[e] == 1)
                        {
                            int x = u[e];
                            int y = v[e];
                            to[edgeIdx] = y; edgeId[edgeIdx] = e; next[edgeIdx] = head[x]; head[x] = edgeIdx++;
                            to[edgeIdx] = x; edgeId[edgeIdx] = e; next[edgeIdx] = head[y]; head[y] = edgeIdx++;
                        }
                    }

                    int* cycleEdges = stackalloc int[n];
                    int cycleEdgeCount = 0;
                    bool pathFound = false;

                    void DfsPath(int curr, int target, int parentEdge)
                    {
                        if (curr == target)
                        {
                            pathFound = true;
                            return;
                        }
                        for (int edge = head[curr]; edge != -1; edge = next[edge])
                        {
                            int neighbor = to[edge];
                            int idVal = edgeId[edge];
                            if (idVal != parentEdge)
                            {
                                cycleEdges[cycleEdgeCount++] = idVal;
                                DfsPath(neighbor, target, idVal);
                                if (pathFound)
                                {
                                    return;
                                }
                                cycleEdgeCount--;
                            }
                        }
                    }

                    DfsPath(r, other, -1);

                    int maxEdgeInCycle = -1;
                    for (int idxC = 0; idxC < cycleEdgeCount; idxC++)
                    {
                        int ec = cycleEdges[idxC];
                        if (u[ec] != r && v[ec] != r)
                        {
                            if (maxEdgeInCycle == -1 || w[ec] > w[maxEdgeInCycle])
                            {
                                maxEdgeInCycle = ec;
                            }
                        }
                    }

                    if (maxEdgeInCycle != -1)
                    {
                        long reduction = w[maxEdgeInCycle] - w[eAdd];
                        if (reduction > maxReduction)
                        {
                            maxReduction = reduction;
                            bestEdgeToAdd = eAdd;
                            bestEdgeToRemove = maxEdgeInCycle;
                        }
                    }
                }

                if (bestEdgeToAdd != -1 && maxReduction > 0)
                {
                    inTree[bestEdgeToAdd] = 1;
                    inTree[bestEdgeToRemove] = 0;
                    deg++;
                }
                else
                {
                    break;
                }
            }

            *resultCount = 0;
            for (int i = 0; i < m; i++)
            {
                if (inTree[i] == 1)
                {
                    resultEdges[(*resultCount)++] = i;
                }
            }

            return true;
        }

        public static void CapacitatedMst(int n, int m, int* u, int* v, long* w, int r, int capacity, int* resultEdges, int* resultCount)
        {
            byte* inTree = stackalloc byte[m];
            for (int i = 0; i < m; i++)
            {
                inTree[i] = 0;
            }

            int* componentSize = stackalloc int[n];
            int* parent = stackalloc int[n];
            for (int i = 0; i < n; i++)
            {
                componentSize[i] = 1;
                parent[i] = i;
            }

            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            int* rootEdge = stackalloc int[n];
            for (int i = 0; i < n; i++)
            {
                rootEdge[i] = -1;
            }

            for (int i = 0; i < m; i++)
            {
                if (u[i] == r || v[i] == r)
                {
                    int other = (u[i] == r) ? v[i] : u[i];
                    if (rootEdge[other] == -1 || w[i] < w[rootEdge[other]])
                    {
                        rootEdge[other] = i;
                    }
                }
            }

            for (int i = 0; i < n; i++)
            {
                if (i != r && rootEdge[i] != -1)
                {
                    inTree[rootEdge[i]] = 1;
                }
            }

            while (true)
            {
                int bestEdge = -1;
                long bestSavings = long.MinValue;
                int mergeU = -1;
                int mergeV = -1;

                for (int e = 0; e < m; e++)
                {
                    if (u[e] == r || v[e] == r)
                    {
                        continue;
                    }
                    if (inTree[e] == 1)
                    {
                        continue;
                    }

                    int ru = Find(u[e]);
                    int rv = Find(v[e]);
                    if (ru == rv)
                    {
                        continue;
                    }

                    if (componentSize[ru] + componentSize[rv] > capacity)
                    {
                        continue;
                    }

                    int reU = rootEdge[ru];
                    int reV = rootEdge[rv];
                    if (reU == -1 || reV == -1)
                    {
                        continue;
                    }

                    long rootCost = Math.Max(w[reU], w[reV]);
                    long savings = rootCost - w[e];
                    if (savings > bestSavings)
                    {
                        bestSavings = savings;
                        bestEdge = e;
                        mergeU = ru;
                        mergeV = rv;
                    }
                }

                if (bestEdge != -1 && bestSavings > 0)
                {
                    inTree[bestEdge] = 1;
                    int reU = rootEdge[mergeU];
                    int reV = rootEdge[mergeV];
                    if (w[reU] > w[reV])
                    {
                        inTree[reU] = 0;
                        rootEdge[mergeU] = reV;
                        parent[mergeU] = mergeV;
                        componentSize[mergeV] += componentSize[mergeU];
                    }
                    else
                    {
                        inTree[reV] = 0;
                        rootEdge[mergeV] = reU;
                        parent[mergeV] = mergeU;
                        componentSize[mergeU] += componentSize[mergeV];
                    }
                }
                else
                {
                    break;
                }
            }

            *resultCount = 0;
            for (int i = 0; i < m; i++)
            {
                if (inTree[i] == 1)
                {
                    resultEdges[(*resultCount)++] = i;
                }
            }
        }

        public static void MinimumDiameterSpanningTree(int n, int m, int* u, int* v, long* w, int* resultEdges, int* resultCount)
        {
            long* dist = stackalloc long[n * n];
            int* parent = stackalloc int[n * n];
            const long Inf = 999999999999;
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    dist[i * n + j] = (i == j) ? 0 : Inf;
                    parent[i * n + j] = -1;
                }
            }

            for (int i = 0; i < m; i++)
            {
                int x = u[i];
                int y = v[i];
                if (w[i] < dist[x * n + y])
                {
                    dist[x * n + y] = w[i];
                    dist[y * n + x] = w[i];
                }
            }

            for (int k = 0; k < n; k++)
            {
                FloydWarshallRelaxVia(dist, n, k);
            }

            int bestCenter = 0;
            long minMaxDist = Inf;
            for (int i = 0; i < n; i++)
            {
                long maxDist = EccentricityOf(dist, n, i);
                if (maxDist < minMaxDist)
                {
                    minMaxDist = maxDist;
                    bestCenter = i;
                }
            }

            long* d = stackalloc long[n];
            int* p = stackalloc int[n];
            byte* vis = stackalloc byte[n];
            for (int i = 0; i < n; i++)
            {
                d[i] = Inf;
                p[i] = -1;
                vis[i] = 0;
            }

            d[bestCenter] = 0;
            for (int step = 0; step < n; step++)
            {
                int curr = -1;
                for (int i = 0; i < n; i++)
                {
                    if (vis[i] == 0 && (curr == -1 || d[i] < d[curr]))
                    {
                        curr = i;
                    }
                }
                if (curr == -1 || d[curr] == Inf)
                {
                    break;
                }
                vis[curr] = 1;

                RelaxIncidentEdges(curr, m, u, v, w, d, p);
            }

            *resultCount = 0;
            for (int i = 0; i < n; i++)
            {
                if (p[i] != -1)
                {
                    resultEdges[(*resultCount)++] = p[i];
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void FloydWarshallRelaxVia(long* dist, int n, int k)
        {
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    if (dist[i * n + k] + dist[k * n + j] < dist[i * n + j])
                    {
                        dist[i * n + j] = dist[i * n + k] + dist[k * n + j];
                    }
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long EccentricityOf(long* dist, int n, int i)
        {
            long maxDist = 0;
            for (int j = 0; j < n; j++)
            {
                if (dist[i * n + j] > maxDist)
                {
                    maxDist = dist[i * n + j];
                }
            }
            return maxDist;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void RelaxIncidentEdges(int curr, int m, int* u, int* v, long* w, long* d, int* p)
        {
            for (int e = 0; e < m; e++)
            {
                int x = u[e];
                int y = v[e];
                if (x == curr && d[curr] + w[e] < d[y])
                {
                    d[y] = d[curr] + w[e];
                    p[y] = e;
                }
                if (y == curr && d[curr] + w[e] < d[x])
                {
                    d[x] = d[curr] + w[e];
                    p[x] = e;
                }
            }
        }

        public static void MinimumBottleneckSpanningTree(int n, int m, int* u, int* v, long* w, int* resultEdges, int* resultCount)
        {
            int* parent = stackalloc int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
            }

            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            int* edgeIndices = stackalloc int[m];
            for (int i = 0; i < m; i++)
            {
                edgeIndices[i] = i;
            }

            for (int i = 0; i < m; i++)
            {
                for (int j = i + 1; j < m; j++)
                {
                    if (w[edgeIndices[i]] > w[edgeIndices[j]])
                    {
                        int tmp = edgeIndices[i];
                        edgeIndices[i] = edgeIndices[j];
                        edgeIndices[j] = tmp;
                    }
                }
            }

            *resultCount = 0;
            for (int i = 0; i < m; i++)
            {
                int e = edgeIndices[i];
                int rx = Find(u[e]);
                int ry = Find(v[e]);
                if (rx != ry)
                {
                    parent[rx] = ry;
                    resultEdges[(*resultCount)++] = e;
                }
            }
        }

        public static long MinimumBottleneckPath(int n, int m, int* u, int* v, long* w, int src, int dest)
        {
            int* mstEdges = stackalloc int[n - 1];
            int mstCount = 0;
            MinimumBottleneckSpanningTree(n, m, u, v, w, mstEdges, &mstCount);

            int* head = stackalloc int[n];
            int* next = stackalloc int[n * 2];
            int* to = stackalloc int[n * 2];
            long* weight = stackalloc long[n * 2];
            for (int i = 0; i < n; i++)
            {
                head[i] = -1;
            }

            int edgeIdx = 0;
            for (int i = 0; i < mstCount; i++)
            {
                int e = mstEdges[i];
                int x = u[e];
                int y = v[e];
                long c = w[e];
                to[edgeIdx] = y; weight[edgeIdx] = c; next[edgeIdx] = head[x]; head[x] = edgeIdx++;
                to[edgeIdx] = x; weight[edgeIdx] = c; next[edgeIdx] = head[y]; head[y] = edgeIdx++;
            }

            long maxWeight = 0;
            bool found = false;

            void Dfs(int curr, int target, int parentNode, long currentMax)
            {
                if (curr == target)
                {
                    maxWeight = currentMax;
                    found = true;
                    return;
                }
                for (int edge = head[curr]; edge != -1; edge = next[edge])
                {
                    int neighbor = to[edge];
                    if (neighbor != parentNode)
                    {
                        Dfs(neighbor, target, curr, Math.Max(currentMax, weight[edge]));
                        if (found)
                        {
                            return;
                        }
                    }
                }
            }

            Dfs(src, dest, -1, 0);
            return found ? maxWeight : -1;
        }

        public static void MaximumCapacitySpanningTree(int n, int m, int* u, int* v, long* w, int* resultEdges, int* resultCount)
        {
            int* parent = stackalloc int[n];
            for (int i = 0; i < n; i++)
