        public static bool LexicographicShortestPath(int n, int m, int* u, int* v, long* w, int src, int dest, int* path, int* pathLength)
        {
            long* dist = stackalloc long[n];
            int* parent = stackalloc int[n];
            int* parentEdge = stackalloc int[n];
            byte* vis = stackalloc byte[n];
            const long Inf = 999999999999;
            for (int i = 0; i < n; i++)
            {
                dist[i] = Inf;
                parent[i] = -1;
                parentEdge[i] = -1;
                vis[i] = 0;
            }

            dist[src] = 0;
            for (int step = 0; step < n; step++)
            {
                int curr = -1;
                for (int i = 0; i < n; i++)
                {
                    if (vis[i] == 0 && (curr == -1 || dist[i] < dist[curr]))
                    {
                        curr = i;
                    }
                }
                if (curr == -1 || dist[curr] == Inf)
                {
                    break;
                }
                vis[curr] = 1;

                for (int e = 0; e < m; e++)
                {
                    int x = u[e];
                    int y = v[e];
                    if (x == curr)
                    {
                        RelaxLexEdge(curr, y, w[e], dist, parent, parentEdge, e);
                    }
                    if (y == curr)
                    {
                        RelaxLexEdge(curr, x, w[e], dist, parent, parentEdge, e);
                    }
                }
            }

            if (dist[dest] == Inf)
            {
                *pathLength = 0;
                return false;
            }

            int* tempPath = stackalloc int[n];
            int tempLen = 0;
            int node = dest;
            while (node != src)
            {
                tempPath[tempLen++] = node;
                node = parent[node];
            }
            tempPath[tempLen++] = src;

            *pathLength = tempLen;
            for (int i = 0; i < tempLen; i++)
            {
                path[i] = tempPath[tempLen - 1 - i];
            }
            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void RelaxLexEdge(int curr, int target, long edgeWeight, long* dist, int* parent, int* parentEdge, int e)
        {
            if (dist[curr] + edgeWeight < dist[target])
            {
                dist[target] = dist[curr] + edgeWeight;
                parent[target] = curr;
                parentEdge[target] = e;
            }
            else if (dist[curr] + edgeWeight == dist[target])
            {
                if (parent[target] == -1 || curr < parent[target])
                {
                    parent[target] = curr;
                    parentEdge[target] = e;
                }
            }
        }

        public static void LexicographicMst(int n, int m, int* u, int* v, long* w, int* resultEdges, int* resultCount)
        {
            int* parent = stackalloc int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
            }

            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            int* edgeIndices = stackalloc int[m];
            for (int i = 0; i < m; i++)
            {
                edgeIndices[i] = i;
            }

            for (int i = 0; i < m; i++)
            {
                for (int j = i + 1; j < m; j++)
                {
                    int ei = edgeIndices[i];
                    int ej = edgeIndices[j];
                    bool swap = false;
                    if (w[ei] > w[ej])
                    {
                        swap = true;
                    }
                    else if (w[ei] == w[ej])
                    {
                        int minUi = Math.Min(u[ei], v[ei]);
                        int minUj = Math.Min(u[ej], v[ej]);
                        if (minUi > minUj)
                        {
                            swap = true;
                        }
                        else if (minUi == minUj)
                        {
                            int maxVi = Math.Max(u[ei], v[ei]);
                            int maxVj = Math.Max(u[ej], v[ej]);
                            if (maxVi > maxVj)
                            {
                                swap = true;
                            }
                        }
                    }
                    if (swap)
                    {
                        int tmp = edgeIndices[i];
                        edgeIndices[i] = edgeIndices[j];
                        edgeIndices[j] = tmp;
                    }
                }
            }

            *resultCount = 0;
            for (int i = 0; i < m; i++)
            {
                int e = edgeIndices[i];
                int rx = Find(u[e]);
                int ry = Find(v[e]);
                if (rx != ry)
                {
                    parent[rx] = ry;
                    resultEdges[(*resultCount)++] = e;
                }
            }
        }

        public static bool RandomizedMstVerify(int numVertices, int numEdges, int* u, int* v, long* weight, bool* inMst)
        {
            long* mstW = stackalloc long[numVertices];
            int* parent = stackalloc int[numVertices];
            for (int i = 0; i < numVertices; i++)
            {
                parent[i] = i;
            }

            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            int mstCount = 0;
            for (int i = 0; i < numEdges; i++)
            {
                if (inMst[i])
                {
                    int rx = Find(u[i]);
                    int ry = Find(v[i]);
                    if (rx != ry)
                    {
                        parent[rx] = ry;
                        mstCount++;
                    }
                    else
                    {
                        return false;
                    }
                }
            }

            if (mstCount != numVertices - 1)
            {
                return false;
            }

            int* head = stackalloc int[numVertices];
            int* next = stackalloc int[numVertices * 2];
            int* to = stackalloc int[numVertices * 2];
            long* edgeW = stackalloc long[numVertices * 2];
            for (int i = 0; i < numVertices; i++)
            {
                head[i] = -1;
            }

            int edgeIdx = 0;
            for (int i = 0; i < numEdges; i++)
            {
                if (inMst[i])
                {
                    int x = u[i];
                    int y = v[i];
                    to[edgeIdx] = y; edgeW[edgeIdx] = weight[i]; next[edgeIdx] = head[x]; head[x] = edgeIdx++;
                    to[edgeIdx] = x; edgeW[edgeIdx] = weight[i]; next[edgeIdx] = head[y]; head[y] = edgeIdx++;
                }
            }

            for (int i = 0; i < numEdges; i++)
            {
                if (!inMst[i])
                {
                    int x = u[i];
                    int y = v[i];
                    long w = weight[i];

                    long maxW = 0;
                    bool pathFound = false;

                    void DfsPath(int curr, int target, int parentNode, long currentMax)
                    {
                        if (curr == target)
                        {
                            maxW = currentMax;
                            pathFound = true;
                            return;
                        }
                        for (int edge = head[curr]; edge != -1; edge = next[edge])
                        {
                            int neighbor = to[edge];
                            if (neighbor != parentNode)
                            {
                                DfsPath(neighbor, target, curr, Math.Max(currentMax, edgeW[edge]));
                                if (pathFound)
                                {
                                    return;
                                }
                            }
                        }
                    }

                    DfsPath(x, y, -1, 0);
                    if (w < maxW)
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        public static void KargerSteinMinCut(int n, int m, int* u, int* v, int* bestCutU, int* bestCutV, int* bestCutCount, ref uint seed)
        {
            if (seed == 0) seed = 123456789;
            int* parent = stackalloc int[n];
            int Find(int x)
            {
                int root = x;
                while (root != parent[root])
                {
                    root = parent[root];
                }
                int curr = x;
                while (curr != root)
                {
                    int nxt = parent[curr];
                    parent[curr] = root;
                    curr = nxt;
                }
                return root;
            }

            int minCut = m + 1;
            int* cutU = stackalloc int[m];
            int* cutV = stackalloc int[m];

            int iterations = Math.Max(5, n * n);
            for (int iter = 0; iter < iterations; iter++)
            {
                for (int i = 0; i < n; i++)
                {
                    parent[i] = i;
                }

                int activeVertices = n;
                while (activeVertices > 2)
                {
                    int e = (int)(NextXorShift(ref seed) % (uint)m);
                    int rx = Find(u[e]);
                    int ry = Find(v[e]);
                    if (rx != ry)
                    {
                        parent[rx] = ry;
                        activeVertices--;
                    }
                }

                int cutCount = 0;
                for (int i = 0; i < m; i++)
                {
                    int rx = Find(u[i]);
                    int ry = Find(v[i]);
                    if (rx != ry)
                    {
                        cutU[cutCount] = u[i];
                        cutV[cutCount] = v[i];
                        cutCount++;
                    }
                }

                if (cutCount < minCut)
                {
                    minCut = cutCount;
                    *bestCutCount = cutCount;
                    for (int i = 0; i < cutCount; i++)
                    {
                        bestCutU[i] = cutU[i];
                        bestCutV[i] = cutV[i];
                    }
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static uint NextXorShift(ref uint seed)
        {
            uint x = seed;
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            seed = x;
            return seed;
        }

        public static void NagamochiIbarakiSparseCertificate(int n, int m, int* u, int* v, int k, int* certEdges, int* certCount)
