namespace IAFahim.Graph.Bridges
{
    using System;
    using System.Runtime.CompilerServices;
    using System.Runtime.InteropServices;

    public static unsafe class IncrementalDynamicBridges
    {
        [StructLayout(LayoutKind.Sequential)]
        public struct Node
        {
            public int Parent;
            public int Left;
            public int Right;
            public byte Rev;
            public int Val;
            public int Sum;
            public int LazyCover;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Init(Node* nodes, int n)
        {
            for (int i = 0; i < n; i++)
            {
                nodes[i].Parent = -1;
                nodes[i].Left = -1;
                nodes[i].Right = -1;
                nodes[i].Rev = 0;
                nodes[i].Val = 0;
                nodes[i].Sum = 0;
                nodes[i].LazyCover = 0;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool IsRoot(Node* nodes, int u)
        {
            int p = nodes[u].Parent;
            return p == -1 || (nodes[p].Left != u && nodes[p].Right != u);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PushUp(Node* nodes, int u)
        {
            nodes[u].Sum = nodes[u].Val;
            int l = nodes[u].Left;
            int r = nodes[u].Right;
            if (l != -1) nodes[u].Sum += nodes[l].Sum;
            if (r != -1) nodes[u].Sum += nodes[r].Sum;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void ApplyCover(Node* nodes, int u)
        {
            if (u != -1)
            {
                nodes[u].Val = 0;
                nodes[u].Sum = 0;
                nodes[u].LazyCover = 1;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PushDown(Node* nodes, int u)
        {
            if (nodes[u].Rev != 0)
            {
                int l = nodes[u].Left;
                int r = nodes[u].Right;
                nodes[u].Left = r;
                nodes[u].Right = l;
                if (l != -1) nodes[l].Rev ^= 1;
                if (r != -1) nodes[r].Rev ^= 1;
                nodes[u].Rev = 0;
            }
            if (nodes[u].LazyCover != 0)
            {
                ApplyCover(nodes, nodes[u].Left);
                ApplyCover(nodes, nodes[u].Right);
                nodes[u].LazyCover = 0;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PushAll(Node* nodes, int u)
        {
            if (!IsRoot(nodes, u)) PushAll(nodes, nodes[u].Parent);
            PushDown(nodes, u);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Rotate(Node* nodes, int x)
        {
            int y = nodes[x].Parent;
            int z = nodes[y].Parent;
            int k = nodes[y].Left == x ? 1 : 0;
            if (!IsRoot(nodes, y))
            {
                if (nodes[z].Left == y) nodes[z].Left = x;
                else nodes[z].Right = x;
            }
            nodes[x].Parent = z;
            nodes[y].Parent = x;
            if (k != 0)
            {
                nodes[y].Left = nodes[x].Right;
                if (nodes[x].Right != -1) nodes[nodes[x].Right].Parent = y;
                nodes[x].Right = y;
            }
            else
            {
                nodes[y].Right = nodes[x].Left;
                if (nodes[x].Left != -1) nodes[nodes[x].Left].Parent = y;
                nodes[x].Left = y;
            }
            PushUp(nodes, y);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Splay(Node* nodes, int x)
        {
            PushAll(nodes, x);
            while (!IsRoot(nodes, x))
            {
                int y = nodes[x].Parent;
                int z = nodes[y].Parent;
                if (!IsRoot(nodes, y))
                {
                    if ((nodes[y].Left == x) ^ (nodes[z].Left == y)) Rotate(nodes, x);
                    else Rotate(nodes, y);
                }
                Rotate(nodes, x);
            }
            PushUp(nodes, x);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int Access(Node* nodes, int u)
        {
            int v = -1;
            for (int x = u; x != -1; x = nodes[x].Parent)
            {
                Splay(nodes, x);
                nodes[x].Right = v;
                PushUp(nodes, x);
                v = x;
            }
            Splay(nodes, u);
            return v;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void MakeRoot(Node* nodes, int u)
        {
            Access(nodes, u);
            nodes[u].Rev ^= 1;
            PushDown(nodes, u);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int FindRoot(Node* nodes, int u)
        {
            Access(nodes, u);
            int x = u;
            PushDown(nodes, x);
            while (nodes[x].Left != -1)
            {
                x = nodes[x].Left;
                PushDown(nodes, x);
            }
            Splay(nodes, x);
            return x;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void AddEdge(Node* nodes, int u, int v, int edgeId, ref int bridgeCount)
        {
            MakeRoot(nodes, u);
            if (FindRoot(nodes, v) != u)
            {
                nodes[edgeId].Val = 1;
                nodes[edgeId].Sum = 1;
                MakeRoot(nodes, v);
                nodes[u].Parent = edgeId;
                nodes[edgeId].Parent = v;
                bridgeCount++;
            }
            else
            {
                MakeRoot(nodes, u);
                Access(nodes, v);
                Splay(nodes, v);
                bridgeCount -= nodes[v].Sum;
                ApplyCover(nodes, v);
            }
        }
    }
}

code.BiconnectivityAugmentation.cs:
namespace IAFahim.Graph.Bridges
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class BiconnectivityAugmentation
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void DfsEdge(int u, int p, int* head, int* next, int* to, int* tin, int* low, ref int timer, int* comp, int* stack, ref int top, ref int compCount)
        {
            tin[u] = low[u] = ++timer; stack[top++] = u;
            for (int e = head[u]; e != -1; e = next[e])
            {
                int v = to[e]; if (v == p) continue;
                if (tin[v] != 0) { if (tin[v] < low[u]) low[u] = tin[v]; }
                else { DfsEdge(v, u, head, next, to, tin, low, ref timer, comp, stack, ref top, ref compCount); if (low[v] < low[u]) low[u] = low[v]; }
            }
            if (low[u] == tin[u]) { while (true) { int v = stack[--top]; comp[v] = compCount; if (u == v) break; } compCount++; }
        }

        public static int MinEdgesFor2EdgeConnected(int n, int* head, int* next, int* to)
        {
            if (n <= 1) return 0;
            int* tin = stackalloc int[n], low = stackalloc int[n], comp = stackalloc int[n], stack = stackalloc int[n];
            for (int i = 0; i < n; i++) { tin[i] = 0; low[i] = 0; comp[i] = -1; }
            int timer = 0, top = 0, compCount = 0, trees = 0;
            for (int i = 0; i < n; i++) if (tin[i] == 0) { DfsEdge(i, -1, head, next, to, tin, low, ref timer, comp, stack, ref top, ref compCount); trees++; }
            if (compCount <= 1) return 0;

            int* degree = stackalloc int[compCount];
            for (int i = 0; i < compCount; i++) degree[i] = 0;
            ComputeComponentDegrees(n, head, next, to, comp, degree);

            int leaves = 0, isolated = 0;
            for (int i = 0; i < compCount; i++) { if (degree[i] == 0) isolated++; else if (degree[i] == 1) leaves++; }
            return trees > 1 ? leaves / 2 + isolated + trees - 1 : (leaves + 1) / 2;
        }

        private static void ComputeComponentDegrees(int n, int* head, int* next, int* to, int* comp, int* degree)
        {
            for (int u = 0; u < n; u++)
                for (int e = head[u]; e != -1; e = next[e])
                    if (comp[u] != comp[to[e]]) degree[comp[u]]++;
        }
    }
}

