code.IncrementalConnectivity.cs:
namespace IAFahim.Graph.Connectivity
{
    using System.Runtime.CompilerServices;

    public static unsafe class IncrementalConnectivity
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Init(int* parent, int* size, int n)
        {
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Find(int* parent, int i)
        {
            int root = i;
            while (root != parent[root])
                root = parent[root];
            int curr = i;
            while (curr != root)
            {
                int nxt = parent[curr];
                parent[curr] = root;
                curr = nxt;
            }
            return root;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool Union(int* parent, int* size, int i, int j)
        {
            int rootI = Find(parent, i);
            int rootJ = Find(parent, j);
            if (rootI != rootJ)
            {
                if (size[rootI] < size[rootJ])
                {
                    int t = rootI; rootI = rootJ; rootJ = t;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
                return true;
            }
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool Connected(int* parent, int i, int j)
        {
            return Find(parent, i) == Find(parent, j);
        }
    }
}

code.DynamicReachabilityApprox.cs:
namespace IAFahim.Graph.Connectivity
{
    using System.Runtime.CompilerServices;

    public static unsafe class DynamicReachabilityApprox
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool Run(int* head, int* next, int* to, int n, bool* visited, int u, int v, int maxDepth)
        {
            if (u == v) return true;
            if (maxDepth <= 0) return false;
            for (int i = 0; i < n; i++) visited[i] = false;
            visited[u] = true;
            return Dfs(head, next, to, visited, u, v, maxDepth);
        }

        private static bool Dfs(int* head, int* next, int* to, bool* visited, int u, int v, int maxDepth)
        {
            if (maxDepth <= 0) return false;
            for (int e = head[u]; e != -1; e = next[e])
            {
                int w = to[e];
                if (w == v) return true;
                if (!visited[w])
                {
                    visited[w] = true;
                    if (Dfs(head, next, to, visited, w, v, maxDepth - 1)) return true;
                }
            }
            return false;
        }
    }
}

code.OfflineDynamicMst.cs:
namespace IAFahim.Graph.Connectivity
{
    using System.Runtime.CompilerServices;

    [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]
    public struct RollbackOp
    {
        public int U;
        public int V;
    }

    public static unsafe class OfflineDynamicMst
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Init(int* parent, int* size, int n)
        {
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Find(int* parent, int i)
        {
            while (i != parent[i]) i = parent[i];
            return i;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool Union(int* parent, int* size, int i, int j, RollbackOp* history, ref int historyCount)
        {
            int rootI = Find(parent, i);
            int rootJ = Find(parent, j);
            if (rootI != rootJ)
            {
                if (size[rootI] < size[rootJ])
                {
                    int t = rootI; rootI = rootJ; rootJ = t;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
                history[historyCount].U = rootI;
                history[historyCount].V = rootJ;
                historyCount++;
                return true;
            }
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Rollback(int* parent, int* size, RollbackOp* history, ref int historyCount, int targetCount)
        {
            while (historyCount > targetCount)
            {
                historyCount--;
                int u = history[historyCount].U;
                int v = history[historyCount].V;
                size[u] -= size[v];
                parent[v] = v;
            }
        }
    }
}

